mapper.select:
SELECT 'SECTION:' || sc.id AS evidenceKey, 'SECTION' AS evidenceType, sc.paper_id AS paperId, p.title AS paperTitle, sc.section_id AS sectionId, sc.id AS chunkId, sc.heading, sc.heading_path AS headingPath, sc.content, sc.page_start AS pageStart, sc.page_end AS pageEnd, 1 - (sc.embedding <=> cast(#{vectorStr} AS vector)) AS semanticScore FROM section_chunks sc JOIN papers p ON p.id = sc.paper_id WHERE sc.embedding IS NOT NULL AND 1 - (sc.embedding <=> cast(#{vectorStr} AS vector)) >= #{minScore}
AND sc.paper_id = #{paperId}
ORDER BY sc.embedding <=> cast(#{vectorStr} AS vector) LIMIT #{limit}

SELECT 'SECTION:' || sc.id AS evidenceKey, 'SECTION' AS evidenceType, sc.paper_id AS paperId, p.title AS paperTitle, sc.section_id AS sectionId, sc.id AS chunkId, sc.heading, sc.heading_path AS headingPath, sc.content, sc.page_start AS pageStart, sc.page_end AS pageEnd, ts_rank_cd(sc.search_vector, websearch_to_tsquery('english', #{query})) AS lexicalScore FROM section_chunks sc JOIN papers p ON p.id = sc.paper_id WHERE sc.search_vector @@ websearch_to_tsquery('english', #{query})
AND sc.paper_id = #{paperId}
ORDER BY lexicalScore DESC LIMIT #{limit}

SELECT 'SYMBOL:' || sym.id AS evidenceKey, 'SYMBOL' AS evidenceType, sym.paper_id AS paperId, p.title AS paperTitle, sym.symbol AS heading, concat_ws(' ', sym.symbol, sym.description, sym.definition_formula) AS content, 1 - (sym.embedding <=> cast(#{vectorStr} AS vector)) AS semanticScore FROM paper_symbols sym JOIN papers p ON p.id = sym.paper_id WHERE sym.embedding IS NOT NULL AND 1 - (sym.embedding <=> cast(#{vectorStr} AS vector)) >= #{minScore}
AND sym.paper_id = #{paperId}
ORDER BY sym.embedding <=> cast(#{vectorStr} AS vector) LIMIT #{limit}

SELECT 'SYMBOL:' || sym.id AS evidenceKey, 'SYMBOL' AS evidenceType, sym.paper_id AS paperId, p.title AS paperTitle, sym.symbol AS heading, concat_ws(' ', sym.symbol, sym.description, sym.definition_formula) AS content, ts_rank_cd( to_tsvector('simple', concat_ws(' ', sym.symbol, sym.description, sym.definition_formula)), websearch_to_tsquery('simple', #{query}) ) AS lexicalScore FROM paper_symbols sym JOIN papers p ON p.id = sym.paper_id WHERE to_tsvector('simple', concat_ws(' ', sym.symbol, sym.description, sym.definition_formula)) @@ websearch_to_tsquery('simple', #{query})
AND sym.paper_id = #{paperId}
ORDER BY lexicalScore DESC LIMIT #{limit}

SELECT 'SYMBOL:' || sym.id AS evidenceKey, 'SYMBOL' AS evidenceType, sym.paper_id AS paperId, p.title AS paperTitle, sym.symbol AS heading, concat_ws(' ', sym.symbol, sym.description, sym.definition_formula) AS content, 1.0 AS lexicalScore FROM paper_symbols sym JOIN papers p ON p.id = sym.paper_id WHERE (lower(sym.symbol) = lower(#{query}) OR lower(sym.latex) = lower(#{query}))
AND sym.paper_id = #{paperId}
ORDER BY sym.id LIMIT #{limit}

SELECT 'REFERENCE:' || pr.id AS evidenceKey, 'REFERENCE' AS evidenceType, pr.paper_id AS paperId, p.title AS paperTitle, gr.title AS heading, concat_ws(' ', gr.title, gr.abstract, pr.raw_text) AS content, pr.ref_index AS referenceIndex, 1 - (gr.embedding <=> cast(#{vectorStr} AS vector)) AS semanticScore FROM paper_references pr JOIN global_references gr ON gr.id = pr.global_ref_id JOIN papers p ON p.id = pr.paper_id WHERE gr.embedding IS NOT NULL AND 1 - (gr.embedding <=> cast(#{vectorStr} AS vector)) >= #{minScore}
AND pr.paper_id = #{paperId}
ORDER BY gr.embedding <=> cast(#{vectorStr} AS vector) LIMIT #{limit}

SELECT 'REFERENCE:' || pr.id AS evidenceKey, 'REFERENCE' AS evidenceType, pr.paper_id AS paperId, p.title AS paperTitle, gr.title AS heading, concat_ws(' ', gr.title, gr.abstract, pr.raw_text) AS content, pr.ref_index AS referenceIndex, ts_rank_cd( to_tsvector('english', concat_ws(' ', gr.title, gr.abstract, pr.raw_text)), websearch_to_tsquery('english', #{query}) ) AS lexicalScore FROM paper_references pr JOIN global_references gr ON gr.id = pr.global_ref_id JOIN papers p ON p.id = pr.paper_id WHERE to_tsvector('english', concat_ws(' ', gr.title, gr.abstract, pr.raw_text)) @@ websearch_to_tsquery('english', #{query})
AND pr.paper_id = #{paperId}
ORDER BY lexicalScore DESC LIMIT #{limit}
